package nl.voetbalhub.app;
import android.app.*;import android.content.*;import android.os.Build;import android.content.pm.PackageManager;import org.json.*;import java.util.*;
/** Consent-based news notifications while the app is open; no background push claim. */
public final class NewsNotifications39 implements FeedRepository.Listener {
 private final Activity activity;private boolean initialized;private final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable poll=new Runnable(){public void run(){if(activity.hasWindowFocus())FeedRepository.refresh(false);handler.postDelayed(this,60000);}};
 public NewsNotifications39(Activity a){activity=a;channel(a);FeedRepository.subscribe(a,this);handler.post(poll);}
 public static void channel(Activity a){NotificationManager manager=(NotificationManager)a.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel("veldio_news39","Veldio clubnieuws en columns",NotificationManager.IMPORTANCE_DEFAULT));}
 public void dispose(){handler.removeCallbacks(poll);FeedRepository.unsubscribe(this);}
 public void changed(JSONObject data,boolean loading,boolean failed){if(data==null||loading||failed)return;JSONArray rows=data.optJSONArray("articles");if(rows==null)return;android.content.SharedPreferences p=activity.getSharedPreferences("veldio_tools39",0);long watermark=p.getLong("newsWatermark",0),newest=watermark;NotificationManager manager=(NotificationManager)activity.getSystemService(Context.NOTIFICATION_SERVICE);
  boolean allowed=activity.hasWindowFocus()&&manager.areNotificationsEnabled()&&(Build.VERSION.SDK_INT<33||activity.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED);Set<String> clubs=activity.getSharedPreferences("voethub",0).getStringSet("clubs",Collections.emptySet());
  for(int i=0;i<rows.length();i++)try{JSONObject article=rows.getJSONObject(i);if(!"published".equals(article.optString("status")))continue;long at=java.time.Instant.parse(article.getString("publishedAt")).toEpochMilli();newest=Math.max(newest,at);if(!initialized||watermark==0||at<=watermark||!allowed)continue;boolean column="column".equalsIgnoreCase(article.optString("type"))||"column".equalsIgnoreCase(article.optString("category"));String text=(article.optString("headline")+" "+article.optString("standfirst")).toLowerCase(Locale.ROOT);boolean relevant=column&&p.getBoolean("columns",false);if(!column&&p.getBoolean("clubNews",false))for(String name:clubs)if(text.contains(name.toLowerCase(Locale.ROOT)))relevant=true;if(!relevant)continue;
   Intent launch=activity.getPackageManager().getLaunchIntentForPackage(activity.getPackageName());PendingIntent open=PendingIntent.getActivity(activity,39,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(activity,"veldio_news39"):new Notification.Builder(activity);builder.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(column?"De Derde Helft":"Nieuw clubnieuws").setContentText(article.optString("headline")).setContentIntent(open).setAutoCancel(true);manager.notify(article.optString("id").hashCode(),builder.build());
  }catch(Exception ignored){}initialized=true;p.edit().putLong("newsWatermark",newest).apply();
 }
}
